CREATE TABLE IF NOT EXISTS strategy_version(strategy_id bigint NOT NULL,version varchar(64) NOT NULL,snapshot json NOT NULL,PRIMARY KEY(strategy_id,version)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS v2_activity_pointer(activity_id bigint PRIMARY KEY,strategy_id bigint NOT NULL,version varchar(64) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS award_stock(stock_pool_id varchar(64) PRIMARY KEY,total bigint NOT NULL,available bigint NOT NULL,reserved bigint NOT NULL,allocated bigint NOT NULL,version bigint NOT NULL DEFAULT 0,recovery_status varchar(32) NOT NULL DEFAULT 'ACTIVE',CHECK(total>=0 AND available>=0 AND reserved>=0 AND allocated>=0 AND total=available+reserved+allocated)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS strategy_stock_binding(strategy_id bigint NOT NULL,version varchar(64) NOT NULL,award_id int NOT NULL,stock_pool_id varchar(64) NOT NULL,PRIMARY KEY(strategy_id,version,award_id),FOREIGN KEY(strategy_id,version) REFERENCES strategy_version(strategy_id,version),FOREIGN KEY(stock_pool_id) REFERENCES award_stock(stock_pool_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS award_reservation(draw_order_id varchar(128) PRIMARY KEY,user_id varchar(64) NOT NULL,identity_hash char(64) NOT NULL,request_hash char(64) NOT NULL,state varchar(32) NOT NULL,snapshot json NOT NULL,stock_pool_id varchar(64),quantity bigint NOT NULL DEFAULT 0,recovery_status varchar(32) NOT NULL DEFAULT 'ACTIVE',version bigint NOT NULL DEFAULT 0,last_progress_at datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),CHECK(quantity IN(0,1)),INDEX reservation_recovery(recovery_status,state,last_progress_at,draw_order_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS stock_change_log(change_id bigint AUTO_INCREMENT PRIMARY KEY,stock_pool_id varchar(64) NOT NULL,biz_id varchar(128) NOT NULL,kind varchar(16) NOT NULL,total_delta bigint NOT NULL,available_delta bigint NOT NULL,reserved_delta bigint NOT NULL,allocated_delta bigint NOT NULL,reason varchar(255) NOT NULL,UNIQUE KEY stock_business(stock_pool_id,biz_id,kind)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
